public sealed class AttemptCache(IDatabase redis)
{
    private readonly ConcurrentDictionary<string, Task<string?>> _inflight = new();

    public Task<string?> GetAsync(string attemptId, CancellationToken cancellationToken)
    {
        return _inflight.GetOrAdd(attemptId, id => FillAsync(id, cancellationToken));
    }

    private async Task<string?> FillAsync(string attemptId, CancellationToken cancellationToken)
    {
        try
        {
            var hit = await redis.StringGetAsync(attemptId);
            if (!hit.IsNullOrEmpty)
            {
                return hit.ToString();
            }

            var origin = await LoadOriginAsync(attemptId, cancellationToken);
            await redis.StringSetAsync(attemptId, origin, TimeSpan.FromSeconds(30 + Random.Shared.Next(30)));
            return origin;
        }
        finally
        {
            _inflight.TryRemove(attemptId, out _);
        }
    }
}
